#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    long long m;
    cin >> n >> m;

    vector<int> base(n), ans;
    iota(base.begin(), base.end(), 1);

    for (int i = 1; i <= n; ++i) {
        ans.push_back(m % i);
        m /= i;
    }

    reverse(ans.begin(), ans.end());

    for (int index : ans) {
        cout << base[index] << ' ';
        base.erase(base.begin() + index);
    }
    cout << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    long long m;
    cin >> n >> m;

    vector<int> base(n), ans(n);
    iota(base.begin(), base.end(), 1);

    for (int i = 1; i <= n; ++i) {
        ans[n - i] = static_cast<int>(m % i);
        m /= i;
    }

    for (int i = 0; i < n; ++i) {
        cout << base[ans[i]] << ' ';
        base.erase(base.begin() + ans[i]);
    }
    cout << '\n';

    return 0;
}

